mapper.select:
SELECT u.*, m.major_name, m.department
FROM sys_user u
LEFT JOIN sys_major m ON u.major_id = m.id
WHERE u.deleted = 0

    AND (u.real_name LIKE CONCAT('%',#{keyword},'%') OR u.username LIKE CONCAT('%',#{keyword},'%') OR u.student_no LIKE CONCAT('%',#{keyword},'%'))

AND u.role = #{role}
AND u.major_id = #{majorId}
AND u.status = #{status}
ORDER BY u.create_time DESC
